func  (this *blockchaincom) Sign(path interface{}, optionalArgs ...interface{}) interface{}  {
    api := ccxt.GetArg(optionalArgs, 0, "public")
    _ = api
    method := ccxt.GetArg(optionalArgs, 1, "GET")
    _ = method
    params := ccxt.GetArg(optionalArgs, 2, map[string]interface{} {})
    _ = params
    headers := ccxt.GetArg(optionalArgs, 3, nil)
    _ = headers
    body := ccxt.GetArg(optionalArgs, 4, nil)
    _ = body
    var requestPath interface{} = ccxt.Add("/", this.ImplodeParams(path, params))
    var url interface{} = ccxt.Add(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), api), requestPath)
    var query interface{} = this.Omit(params, this.ExtractParams(path))
    if ccxt.IsTrue(ccxt.IsEqual(api, "public")) {
        if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
            url = ccxt.Add(url, ccxt.Add("?", this.Urlencode(query)))
        }
    } else if ccxt.IsTrue(ccxt.IsEqual(api, "private")) {
        this.CheckRequiredCredentials()
        headers = map[string]interface{} {
            "X-API-Token": this.Secret,
        }
        if ccxt.IsTrue((ccxt.IsEqual(method, "GET"))) {
            if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
                url = ccxt.Add(url, ccxt.Add("?", this.Urlencode(query)))
            }
        } else {
            body = this.Json(query)
            ccxt.AddElementToObject(headers, "Content-Type", "application/json")
        }
    }
    return map[string]interface{} {
        "url": url,
        "method": method,
        "body": body,
        "headers": headers,
    }
}
func  (this *blockchaincom) HandleErrors(code interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    // {"timestamp":"2021-10-21T15:13:58.837+00:00","status":404,"error":"Not Found","message":"","path":"/orders/505050"
    if ccxt.IsTrue(ccxt.IsEqual(response, nil)) {
        return nil
    }
    var text interface{} = this.SafeString(response, "text")
    if ccxt.IsTrue(!ccxt.IsEqual(text, nil)) {
        if ccxt.IsTrue(ccxt.IsEqual(text, "Insufficient ccxt.Balance")) {
            panic(ccxt.InsufficientFunds(ccxt.Add(ccxt.Add(this.Id, " "), body)))
        }
    }
    var errorCode interface{} = this.SafeString(response, "status")
    var errorMessage interface{} = this.SafeString(response, "error")
    if ccxt.IsTrue(!ccxt.IsEqual(code, nil)) {
        var feedback interface{} = ccxt.Add(ccxt.Add(this.Id, " "), this.Json(response))
        this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, feedback)
        this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), errorMessage, feedback)
    }
    return nil
}


